INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('bench_tender', 'ru', 'Тендер на скамейки', 'Подрядчик предлагает откатить за победу в тендере на «золотые» скамейки для парка. Жена тем временем намекает на новый пентхаус.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('tama_38', 'ru', 'Махинации с ТАМА 38', 'Застройщик просит закрыть глаза на три «лишних» этажа в проекте ТАМА 38 в центре города. Обещает занести солидную сумму в швейцарский банк.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shelters_budget', 'ru', 'Бюджет на мамады (Бомбоубежища)', 'Государство выделило огромный бюджет на ремонт старых бомбоубежищ. Брат жены внезапно открыл фирму по установке бронированных дверей.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('state_comptroller', 'ru', 'Проверка Госконтролера', 'В муниципалитет нагрянула проверка от Мевакер ха-Медина. Аудиторы требуют доступ к бухгалтерии за прошлый год.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shabbat_blackmail', 'ru', 'Коалиционный кризис (Шаббат)', 'Религиозные партии угрожают развалить коалицию, если вы не закроете все парки и бизнесы в Шаббат. Жена очень любит гулять по субботам.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lawyer_visit', 'ru', 'Визит адвоката-решалы', 'Известный адвокат предлагает «потерять» пару неприятных папок на вас в Лахав 433 за солидный гонорар.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('garbage_extortion', 'ru', 'Рэкет на мусоре', 'Бравые парни из Калансуа пришли на тендер по вывозу мусора в восточных районах и прозрачно намекнули, что без их «крыши» у мусоровозов могут пробиться колеса.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('neighbor_mayor_amuta', 'ru', 'Братская помощь коллеге', 'Мэр соседней Хадеры звонит в панике: перед выборами срочно нужна «амута» (некоммерческая организация) для сбора пожертвований, просит подбросить на кампанию.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shitty_burger', 'ru', 'Скандал с White Burger', 'В новой бургерной *White Burger*, принадлежащей твоему главному спонсору, инспекторы нашли мясо крайне сомнительного происхождения. Требуют закрыть лавочку.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shabbat_parking', 'ru', 'Субботний парковочный ад', 'Жители светских районов взвыли: по субботам всё заставлено машинами так, что скорая не проедет. Оппозиция требует устроить облаву с эвакуаторами.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('flooded_street', 'ru', 'Потоп на улице Вайцман', 'Прошел первый серьезный ливень, и центральная улица Вайцман уплыла. Бюджет на прочистку ливневок куда-то испарился, а местные паблики уже полощут твое имя.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('burning_trucks', 'ru', 'Горящие мусоровозы', 'Пара дней молчания закончилась: ночью на муниципальной стоянке сгорели три мусоровоза. На асфальте баллончиком написано «Привет из Калансуа». Половина города утопает в отходах.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('kompromat_retaliation', 'ru', 'Ответный удар СМИ', 'Мэр соседней Хадеры не простил слива. В крупном телеграм-канале вышло расследование про твою «неучтенную» виллу в Кесарии и снимки твоей жены в миланском бутике.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('arnona_scandal', 'ru', 'Скидки по Арноне для избранных', 'Журналисты выяснили, что бизнес вашего крупного спонсора получает 80% скидку на земельный налог (арнону).');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('beach_kiosk', 'ru', 'Захват городского пляжа', 'Владелец пляжного ресторана без разрешения захватил 200 метров береговой линии и поставил платные шезлонги.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('electric_scooters', 'ru', 'Нашествие электросамокатов', 'Жители разгневаны: самокаты бросают на тротуарах, а гонщики сбивают пенсионеров.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('stadium_naming', 'ru', 'Права на название стадиона', 'Олигарх хочет переименовать городской стадион в честь своей коммерческой компании.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('sewage_overflow', 'ru', 'Прорыв канализации', 'Главный коллектор не выдержал нагрузок. Набережная затапливается нечистотами.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('friday_country_club', 'ru', 'Пятничные встречи в Кантри-клубе', 'Каждую пятницу в 8:00 утра вы сидите в шезлонге у бассейна Кантри. К вам выстраивается очередь из знакомых и незнакомцев с «маленькими просьбами».');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('country_cctv_raid', 'ru', 'Изъятие записей в Кантри', 'Следователи Лахав 433 явились в администрацию Кантри-клуба и требуют серверы с камерами видеонаблюдения за прошлую пятницу.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('kindergarten_favor', 'ru', 'Блат в детском саду', 'Старый друг пришел к вам в кабинет с просьбой срочно перевести его ребенка в элитный садик в центре города, хотя мест давно нет.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('metro_depot', 'ru', 'Строительство депо метро', 'Министерство транспорта предлагает построить гигантское депо метро в черте города. Подрядчики в восторге, но жители в гневе из-за шума и стройки.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('bagrut_success', 'ru', 'Реформа школьного образования', 'Городу подвернулся шанс поднять процент сдавших Багрут на рекордный уровень, но гордепартамент образования просит солидный бюджет на репетиторов и лаборатории.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('park_sculptures', 'ru', 'Современное искусство в парке', 'Ваш близкий друг-скульптор предлагает уставить центральный городской парк своими абстрактными статуями из ржавого железа за счет бюджета.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('yom_haatzmaut', 'ru', 'Празднование Дня Независимости', 'Главное событие года! Спонсоры перевели миллионы на праздничный концерт, салюты и угощения. Полиция в этот день праздники не портит.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wife_dog_park', 'ru', 'Собака для жены', 'Жена хочет собаку, но в районе нет площадки для выгула.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('cat_exhibition', 'ru', 'Выставка кошек', 'Жена познакомилась с местным клубом любителей кошек и просит организовать городскую выставку.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lgbt_parade', 'ru', 'Парад Гордости на улице Вайцман', 'Организаторы просят разрешение провести Парад Гордости на центральной улице города. Тема вызвала бурные споры.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lgbt_coalition_crisis', 'ru', 'Кризис в коалиции', 'Религиозные партнеры по коалиции в бешенстве от прошедшего парада и требуют немедленно закрыть городской ЛГБТ-клуб.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('mayors_strip_club', 'ru', 'Скандал после встречи мэров', 'После ежегодного съезда мэров вы пошли отмечать в стрип-клуб. Пресса узнала об этом и устроила вам головомойку.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('mayors_revenge', 'ru', 'Ответка союза мэров', 'Мэры соседних городов узнали, кто слил их фотографии в стрип-клубе прессе, и решили объединиться против вас.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('son_wedding', 'ru', 'Свадьба сына', 'Ваш сын женится. Это отличное событие и поворотный момент для всей семьи.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wedding_investigation', 'ru', 'Расследование по свадьбе', 'Журналисты пронюхали, что на пышной свадьбе сына вам передавали взятки под видом подарков.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('father_funeral', 'ru', 'Траур и похороны отца', 'В семье stem-трагедия: скончался ваш отец. Время проведения шивы и приема соболезнований.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('father_monument_offer', 'ru', 'Памятник от застройщиков', 'Влиятельные застройщики, приходившие на шиву, предлагают полностью оплатить элитный памятник вашему отцу.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('daughter_school', 'ru', 'Дочка идет в школу', 'Формирование классов на новый учебный год. Пора решить, с кем будет учиться ваша дочь.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('school_flood', 'ru', 'Потоп в школе', 'В школе дочери прорвало старые трубы, классы полностью затоплены.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('bench_tender', 'en', 'Park Benches Tender', 'A contractor offers a kickback to win a tender for ''luxury'' park benches. Meanwhile, your wife is hinting about a new penthouse.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('tama_38', 'en', 'TAMA 38 Shenanigans', 'A developer asks you to turn a blind eye to three ''extra'' floors in a downtown TAMA 38 project. He promises a solid deposit to a Swiss bank.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shelters_budget', 'en', 'Bomb Shelters Budget', 'The state allocated a huge budget to renovate old bomb shelters. Your brother-in-law suddenly opened an armored doors company.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('state_comptroller', 'en', 'State Comptroller Audit', 'A surprise audit from the State Comptroller hits the municipality. The auditors demand access to last year''s accounting books.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shabbat_blackmail', 'en', 'Coalition Crisis (Shabbat)', 'Religious parties threaten to dismantle the coalition unless you close all parks and businesses on Shabbat. Your wife loves Saturday strolls.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lawyer_visit', 'en', 'Visit from a Fixer Lawyer', 'A well-known fixer lawyer offers to ''lose'' a couple of unpleasant files on you in Lahav 433 for a hefty fee.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('garbage_extortion', 'en', 'Garbage Extortion', 'Tough guys from Qalansawe showed up at the waste management tender, hinting that without their ''protection'', garbage trucks might get flat tires.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('neighbor_mayor_amuta', 'en', 'Brotherly Help to a Colleague', 'The mayor of Hadera panics: ahead of the elections, he urgently needs an ''amuta'' (nonprofit) for donations and asks for campaign backing.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shitty_burger', 'en', 'The White Burger Scandal', 'Inspectors found highly questionable meat at *White Burger*, owned by your main campaign donor. They are demanding an immediate shutdown.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shabbat_parking', 'en', 'Shabbat Parking Hell', 'Secular neighborhood residents are furious: streets are blocked so badly an ambulance can''t pass. The opposition demands a towing crackdown.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('flooded_street', 'en', 'Weizmann Street Flood', 'The first serious rain hit, and central Weizmann Street is completely underwater. The drainage maintenance budget vanished, and local news is roasting you.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('burning_trucks', 'en', 'Burning Garbage Trucks', 'A few days of calm are over: three garbage trucks burned overnight at the municipal depot. The words "Greetings from Qalansuwa" are spray-painted on the asphalt. Half the city is drowning in waste.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('kompromat_retaliation', 'en', 'Media Counterattack', 'The mayor of Hadera hasn''t forgiven you for the leak. A major Telegram channel has published an investigation about your "undeclared" villa in Caesarea and photos of your wife at a Milan boutique.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('arnona_scandal', 'en', 'Arnona Tax Scandal', 'Reporters found that your campaign donor gets an 80% property tax (Arnona) discount.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('beach_kiosk', 'en', 'Public Beach Land Grab', 'A beach restaurant owner illegally seized 200m of public coastline for paid sunbeds.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('electric_scooters', 'en', 'Electric Scooter Chaos', 'Residents are furious about e-scooters cluttering sidewalks and knocking over pedestrians.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('stadium_naming', 'en', 'Stadium Naming Rights', 'An oligarch wants to rename the municipal stadium after his holding company.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('sewage_overflow', 'en', 'Main Sewage Pipe Burst', 'The main sewer line burst, flooding the seafront promenade with wastewater.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('friday_country_club', 'en', 'Friday Country Club Morning', 'Every Friday at 8:00 AM you sit by the Country Club pool. A queue of locals forms with ''small personal requests''.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('country_cctv_raid', 'en', 'Country Club CCTV Raid', 'Lahav 433 investigators arrive at the Country Club and demand the surveillance servers from last Friday.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('kindergarten_favor', 'en', 'Kindergarten Favoritism', 'An old friend comes to your office asking to urgently transfer his kid into an elite downtown kindergarten, even though enrollment is closed.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('metro_depot', 'en', 'Metro Depot Proposal', 'The Ministry of Transport wants to build a massive metro depot in your city. Contractors are thrilled, but residents are furious about the noise and construction.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('bagrut_success', 'en', 'High School Exam Reform', 'There is a chance to boost Bagrut exam pass rates to a record high, but the education department requests a big budget for tutors and labs.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('park_sculptures', 'en', 'Modern Art in the City Park', 'Your sculptor friend offers to place abstract rusty iron statues in the main park at municipal expense.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('yom_haatzmaut', 'en', 'Independence Day Celebration', 'The biggest event of the year! Sponsors transferred millions for concerts and fireworks. Police don''t bother anyone on holidays.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wife_dog_park', 'en', 'A Dog for the Wife', 'Your wife wants a dog, but there is no dog park in the neighborhood.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('cat_exhibition', 'en', 'Cat Exhibition', 'Your wife met a local cat-lovers club and asks you to organize a city exhibition.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lgbt_parade', 'en', 'Pride Parade on Weizmann Street', 'Organizers ask permission to hold a Pride Parade on the city''s central street. The issue has caused fierce debate.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lgbt_coalition_crisis', 'en', 'Coalition Crisis', 'Your religious coalition partners are furious about the parade and demand the city''s LGBT club close immediately.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('mayors_strip_club', 'en', 'Scandal after the Mayors'' Meeting', 'After the annual mayors'' convention, you went to celebrate at a strip club. The press found out and gave you a public beating.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('mayors_revenge', 'en', 'The Mayors'' Alliance Strikes Back', 'Mayors from neighboring cities discovered who leaked their strip-club photos to the press and decided to unite against you.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('son_wedding', 'en', 'Son''s Wedding', 'Your son is getting married. It is an excellent event and a turning point for the whole family.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wedding_investigation', 'en', 'Wedding Investigation', 'Journalists discovered that bribes were handed to you as gifts at your son''s lavish wedding.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('father_funeral', 'en', 'Mourning and Father''s Funeral', 'A family tragedy: your father has died. It is time for shiva and receiving condolences.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('father_monument_offer', 'en', 'Monument from Developers', 'Influential developers who visited the shiva offer to pay for an elite monument for your father.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('daughter_school', 'en', 'Daughter Starts School', 'Classes are being formed for the new school year. It is time to decide who your daughter will study with.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('school_flood', 'en', 'School Flood', 'Old pipes burst at your daughter''s school, completely flooding the classrooms.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('bench_tender', 'he', 'מכרז על ספסלים', 'קבלן מציע עמלה על זכייה במכרז לספסלי יוקרה בפארק. אשתך רומזת על פנטהאוז חדש.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('tama_38', 'he', 'קומבינות בתמ"א 38', 'יזם מבקש להעלים עין משלוש קומות "מיותרות" בפרויקט תמ"א 38 במרכז העיר. מבטיח להעביר סכום נכבד לחשבון בשווייץ.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shelters_budget', 'he', 'תקציב לממ"דים', 'המדינה הקצתה תקציב ענק לשיפוץ ממ"דים ישנים. גיסך פתח לפתע חברה להתקנת דלתות פלדה.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('state_comptroller', 'he', 'ביקורת מבקר המדינה', 'ביקורת פתע של מבקר המדינה בעירייה. הרואי חשבון דורשים גישה לספרי החשבונות של השנה שעברה.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shabbat_blackmail', 'he', 'משבר קואליציוני (שבת)', 'המפלגות הדתיות מאיימות לפרק את הקואליציה אם לא תסגור את כל הפארקים והעסקים בשבת. אשתך מאוד אוהבת לטייל בשבתות.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lawyer_visit', 'he', 'ביקור של עורך דין מקושר', 'עורך דין מוכר מציע "לאבד" כמה תיקים לא נעימים עליך בלהב 433 תמורת שכר טרחה שמן.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('garbage_extortion', 'he', 'פרוטקשן על אשפה', 'חבר''ה קשוחים מקלנסווה הגיעו למכרז פינוי האשפה ורמזו בעדינות שבלי ה''חסות'' שלהם למשאיות יהיו פנצ''רים.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('neighbor_mayor_amuta', 'he', 'עזרה אחים לעמית', 'ראש עיריית חדרה מתקשר בפאניקה: לקראת הבחירות חייבים ''עמותה'' לגיוס תרומות, ומבקש שתעזור במימון הקמפיין.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shitty_burger', 'he', 'השערוריה ב-White Burger', 'במסעדה החדשה *White Burger* של התורם הראשי שלך נתפסו בשרים מוטלים בספק. הפקחים דורשים לסגור את המקום.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('shabbat_parking', 'he', 'גיהנום החניה בשבת', 'תושבי השכונות החילוניות זועמים: בשבת הכל חסום ואמבולנס לא יכול לעבור. האופוזיציה דורשת לפנות רכבים באגרסיביות.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('flooded_street', 'he', 'ההצפה ברחוב ויצמן', 'הגשם הרציני הראשון ירד, ורחוב ויצמן המרכזי הפך לנהר. התקציב לניקוי ניקוזים נעלם לאן שהוא, והעמודים המקומיים כבר קורעים לגזרים את השם שלך.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('burning_trucks', 'he', 'משאיות האשפה הבוערות', 'כמה ימים של שקט הגיעו לסיומם: בלילה נשרפו שלוש משאיות אשפה בחניון העירוני. על האספלט רוססו המילים "דרישת שלום מקלנסווה". חצי עיר טובעת בזבל.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('kompromat_retaliation', 'he', 'מתקפת נגד תקשורתית', 'ראש עיריית חדרה לא סלח לך על ההדלפה. בערוץ טלגרם גדול פורסם תחקיר על הווילה "הלא מדווחת" שלך בקיסריה, לצד תמונות של אשתך בבוטיק במילאנו.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('arnona_scandal', 'he', 'שערוריית הנחת הארנונה', 'עיתונאים גילו שתורם מרכזי לקמפיין שלך מקבל 80% הנחה בארנונה לעסקים.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('beach_kiosk', 'he', 'שתלטנות על החוף העירוני', 'בעל מסעדת חוף השתלט ללא היתר על 200 מטרים של קו החוף והציב מיטות שיזוף בתשלום.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('electric_scooters', 'he', 'כאוס הקורקינטים החשמליים', 'התושבים זועמים על קורקינטים שחוסמים מדרכות ומסכנים הולכי רגל.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('stadium_naming', 'he', 'זכויות שם האצטדיון', 'אוליגרך מבקש לקרוא לאצטדיון העירוני על שם החברה המסחרית שלו.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('sewage_overflow', 'he', 'פיצוץ בצינור הביוב המרכזי', 'צינור הביוב הראשי התפוצץ והציף את הטיילת בשפכים.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('friday_country_club', 'he', 'מפגשי יום שישי בקאנטרי', 'בכל יום שישי ב-8:00 בבוקר אתה יושב ליד הבריכה בקאנטרי. תור של תושבים ומכרים מגיע עם "בקשות קטנות".');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('country_cctv_raid', 'he', 'פשיטה על מצלמות הקאנטרי', 'חוקרי להב 433 הגיעו להנהלת הקאנטרי ודורשים את שרתי מצלמות האבטחה מיום שישי האחרון.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('kindergarten_favor', 'he', 'פרוטקציה בגן הילדים', 'חבר ילדות קרוב מגיע אליך למשרד ומבקש להעביר בדחיפות את הילד שלו לגן היוקרתי במרכז העיר, למרות שההרשמה סגורה.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('metro_depot', 'he', 'הקמת דפו מטרו בעיר', 'משרד התחבורה מציע להקים דפו מטרו ענקי בשטח העיר. הקבלנים נלהבים, אך התושבים זועמים על הרעש והעבודות.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('bagrut_success', 'he', 'רפורמה בבחינות הבגרות', 'יש הזדמנות להעלות את אחוז הזכאים לבגרות לשיא עירוני, אך אגף החינוך דורש תקציב עתק לתגבורים ומעבדות.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('park_sculptures', 'he', 'אמנות מודרנית בפארק העירוני', 'חבר קרוב שהוא פסל מציע להציב בפארק המרכזי פסלי ברזל מופשטים בעלות עתק על חשבון העירייה.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('yom_haatzmaut', 'he', 'חגיגות יום העצמאות', 'האירוע הגדול של השנה! ספונסרים העבירו מיליונים להופעות, זיקוקים ואוכל. המשטרה לא מתערבת בחג.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wife_dog_park', 'he', 'כלב לאישה', 'אשתך רוצה כלב, אבל בשכונה אין גינת כלבים.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('cat_exhibition', 'he', 'תערוכת חתולים', 'אשתך הכירה מועדון מקומי של חובבי חתולים ומבקשת לארגן תערוכה עירונית.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lgbt_parade', 'he', 'מצעד הגאווה ברחוב וייצמן', 'המארגנים מבקשים אישור לקים את מצעד הגאווה ברחוב המרכזי. הנושא מחולל סערה בעיר.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('lgbt_coalition_crisis', 'he', 'משבר בקואליציה', 'השותפים הדתיים בקואליציה זועמים על המצעד ודורשים לסגור מיידית את מועדון הקהילה בעיר.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('mayors_strip_club', 'he', 'סערת מועדון החשפנות', 'אחרי כנס ראשי הערים הלכתם לחגוג במועדון חשפנות. התקשורת גילתה וחוגגת על החשבון.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('mayors_revenge', 'he', 'נקמת ראשי הערים', 'ראשי הערים השכנות גילו שאתה זה שהדליף את התמונות שלהם לתקשורת, והחליטו לאחד כוחות נגדך.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('son_wedding', 'he', 'חתונת הבן', 'הבן שלך מתחתן. אירוע מרגש ונקודת ציון חשובה לכל המשפחה.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('wedding_investigation', 'he', 'תחקיר החתונה', 'עיתונאים גילו שבחסות החתונה המפוארת של הבן הועברו אליך שוחד ומעטפות מאינטרסנטים.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('father_funeral', 'he', 'שבעה והלוויית האב', 'טרגדיה במשפחה: אביך הלך לעולמו. זמן לשבעה וקבלת מנחמים.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('father_monument_offer', 'he', 'מצבה מהיזמים', 'יזמים חזקים שהגיעו לנחם מציעים לממן מכיסם מצבה מפוארת ויוקרתית לאביך.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('daughter_school', 'he', 'הבת עולה לכיתה א''', 'שיבוץ הכיתות לשנת הלימודים. הגיע הזמן להחליט עם מי תלמד הבת שלך.');
INSERT OR REPLACE INTO game_event_locales (event_id, lang, title, description) VALUES ('school_flood', 'he', 'הצפה בבית הספר', 'צינור ראשי התפוצץ בבית הספר של הבת, הכיתות מוצפות לחלוטין.');

